USE `gmodelo_dbp`;
SET NAMES utf8mb4;
CREATE OR REPLACE VIEW `vw_responsabilidade_ml_controles` AS
SELECT a.CODATRIBUICAO,d.CODDOCUMENTO,d.CODIGO,d.TITULO,rt.CODIGO TIPO_CODIGO,rt.NOME TIPO_NOME,a.TIPO_DESTINO,a.CODUSUARIO,u.userid RESPONSAVEL_USUARIO,u.nome RESPONSAVEL_NOME,a.CODGRUPO,g.nome RESPONSAVEL_GRUPO,CASE WHEN a.TIPO_DESTINO='USUARIO' THEN COALESCE(NULLIF(TRIM(u.nome),''),u.userid,CONCAT('Usuario ',a.CODUSUARIO)) ELSE COALESCE(g.nome,CONCAT('Grupo ',a.CODGRUPO)) END RESPONSAVEL_EXIBICAO,a.ORIGEM,a.ENTIDADE,a.REGISTRO_ID,a.PRIORIDADE,a.PRINCIPAL,a.VALIDO_DE,a.VALIDO_ATE,a.ATIVO
FROM responsabilidade_atribuicoes a INNER JOIN documentos d ON a.ENTIDADE='documentos' AND CAST(a.REGISTRO_ID AS UNSIGNED)=d.CODDOCUMENTO LEFT JOIN responsabilidade_tipos rt ON rt.CODTIPORESPONSABILIDADE=a.CODTIPORESPONSABILIDADE LEFT JOIN usuarios u ON u.codusuario=a.CODUSUARIO LEFT JOIN grupos g ON g.codgrupo=a.CODGRUPO WHERE a.ENTIDADE='documentos';
CREATE OR REPLACE VIEW `vw_meus_controles_grid` AS
SELECT DISTINCT d.CODDOCUMENTO,d.CODIGO,d.TITULO,g.ARQUIVO,g.UNIDADES,g.ATIVIDADES,g.ASPECTOS,g.IMPACTOS,g.PERIGOS,g.RISCOS,g.PALAVRAS_CHAVES,g.RESPONSAVEIS,g.ASPECTOS_SOCIAIS,g.IMPACTOS_SOCIAIS,a.CODUSUARIO FROM documentos d INNER JOIN vw_controle_documentos_grid g ON g.CODDOCUMENTO=d.CODDOCUMENTO INNER JOIN responsabilidade_atribuicoes a ON a.ENTIDADE='documentos' AND a.REGISTRO_ID=CAST(d.CODDOCUMENTO AS CHAR) AND a.TIPO_DESTINO='USUARIO' AND a.CODUSUARIO IS NOT NULL AND a.ATIVO=1 AND a.VALIDO_DE<=CURRENT_DATE AND (a.VALIDO_ATE IS NULL OR a.VALIDO_ATE>=CURRENT_DATE)
UNION SELECT DISTINCT d.CODDOCUMENTO,d.CODIGO,d.TITULO,g.ARQUIVO,g.UNIDADES,g.ATIVIDADES,g.ASPECTOS,g.IMPACTOS,g.PERIGOS,g.RISCOS,g.PALAVRAS_CHAVES,g.RESPONSAVEIS,g.ASPECTOS_SOCIAIS,g.IMPACTOS_SOCIAIS,gu.CODUSUARIO FROM documentos d INNER JOIN vw_controle_documentos_grid g ON g.CODDOCUMENTO=d.CODDOCUMENTO INNER JOIN responsabilidade_atribuicoes a ON a.ENTIDADE='documentos' AND a.REGISTRO_ID=CAST(d.CODDOCUMENTO AS CHAR) AND a.TIPO_DESTINO='GRUPO' AND a.CODGRUPO IS NOT NULL AND a.ATIVO=1 AND a.VALIDO_DE<=CURRENT_DATE AND (a.VALIDO_ATE IS NULL OR a.VALIDO_ATE>=CURRENT_DATE) INNER JOIN responsabilidade_grupoxusuario gu ON gu.CODGRUPO=a.CODGRUPO AND gu.ATIVO=1;
INSERT INTO menus (codmenu_pai,modulo,codigo,label,label_pt,label_en,label_es,url,nivel,ordem,ativo) SELECT p.codmenu,'MODULO_LEGAL','MEUS_CONTROLES','Meus Controles','Meus Controles','My Controls','Mis Controles','/principal/meus_controles.php',2,41,1 FROM menus p WHERE p.codigo='MODULO_LEGAL' AND NOT EXISTS (SELECT 1 FROM menus m WHERE m.codigo='MEUS_CONTROLES');
UPDATE menus SET codmenu_pai=(SELECT codmenu FROM (SELECT codmenu FROM menus WHERE codigo='MODULO_LEGAL') x),modulo='MODULO_LEGAL',ordem=41,url='/principal/meus_controles.php',ativo=1 WHERE codigo='MEUS_CONTROLES';
INSERT INTO permissoes (codperfil,codmenu,pode_incluir,pode_visualizar,pode_visualizar_total,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) SELECT p.codperfil,m.codmenu,0,COALESCE(o.pode_visualizar,0),0,COALESCE(o.pode_editar,0),0,COALESCE(o.pode_exportar_excel,0),0 FROM perfis p CROSS JOIN menus m LEFT JOIN permissoes o ON o.codperfil=p.codperfil AND o.codmenu=(SELECT codmenu FROM menus WHERE codigo='CONTROLE_DOCUMENTOS') WHERE m.codigo='MEUS_CONTROLES' AND NOT EXISTS (SELECT 1 FROM permissoes x WHERE x.codperfil=p.codperfil AND x.codmenu=m.codmenu);
